// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint64 startTime, address actor1, address actor2) public {
        vm.assume(startTime > 0);
        vm.assume(actor1 != address(0) && actor1 != address(c));
        vm.assume(actor2 != address(0) && actor2 != address(c) && actor2 != actor1);

        uint256 amount = 10 ether;

        // First successful call at time startTime
        vm.warp(startTime);
        vm.deal(actor1, amount);
        vm.prank(actor1);
        (bool ok1, ) = address(c).call{value: amount}("");
        assertTrue(ok1, "first call at fresh timestamp must succeed");

        // Second call at the SAME timestamp must revert (strict rule: timestamp must strictly increase)
        vm.deal(actor2, amount);
        vm.prank(actor2);
        (bool ok2, ) = address(c).call{value: amount}("");
        assertTrue(!ok2, "second call at the same block.timestamp must revert");
    }
}
